  'guide.reports.title': 'রিপোর্ট দেখুন',
  'guide.create.why': 'বাকি সবকিছু প্রতিষ্ঠানের সঙ্গে যুক্ত, তাই এখান থেকে শুরু করুন। আপনি এর মালিক হবেন।',
  'guide.venues.why': 'সেশন, কোর্ট ও ফি ভেন্যুর সঙ্গে যুক্ত, তাই প্রোগ্রাম পরিকল্পনার আগে আপনার প্রশিক্ষণের জায়গাগুলো যোগ করুন।',
  'guide.staff.why': 'কোচ, ফ্রন্ট ডেস্ক ও ফাইন্যান্সকে আলাদা অ্যাক্সেস দিন। প্রত্যেকে শুধু নিজের ভূমিকার জন্য প্রয়োজনীয়টুকু দেখেন।',
  'guide.suppliers.why': 'রক্ষণাবেক্ষণ ঠিকাদার ও কিট সরবরাহকারীদের এক জায়গায় রাখুন, তারা যে ভেন্যুতে সেবা দেয় তার সঙ্গে যুক্ত করুন, অনুরোধ শেষ না হওয়া পর্যন্ত ট্র্যাক করুন।',
  'guide.programmes.why': 'প্রোগ্রাম হলো যা পরিবারগুলো কেনে: একটি স্কোয়াড, টার্ম কোর্স বা ক্যাম্প, দাম ও আসন সহ।',
  'guide.coaches.why': 'কোচদের কর্মী, ঠিকাদার বা আয়-অংশীদার হিসেবে আনুন এবং শর্তগুলো লিখিতভাবে ঠিক করুন।',
  'guide.students.why': 'অনুসন্ধান থেকে ভর্তি পর্যন্ত মানুষকে এগিয়ে নিন। শিশুদের জন্য অভিভাবকেরা সম্মতি দেন।',
  'guide.classes.why': 'আজ ও সপ্তাহ এক নজরে দেখুন, উপস্থিতি নিন এবং মেক-আপ ও বাতিল ক্লাস দৃশ্যমান রাখুন।',
  'guide.tax.why': 'আদায় ও পরিশোধ করা কর জানুন, আপনার কর নিয়ম ও ইনভয়েসে কর তথ্য সহ।',
  'guide.revenue.why': 'কোচদের সঙ্গে অর্থ কীভাবে ভাগ হবে এবং যৌথ খরচ প্রোগ্রামগুলোতে কীভাবে বণ্টিত হবে তা ঠিক করুন।',
  'guide.reports.why': 'এক্সিকিউটিভ হোমে ফলাফল, ধরে রাখা, আর্থিক অবস্থা ও অংশীদার দেখুন এবং যা দরকার এক্সপোর্ট করুন।',
  'dp.tab': 'উন্নয়ন পরিকল্পনা',
