  'dp.new_notice': 'একটি পরিকল্পনা এক মৌসুমের জন্য একজন অ্যাথলিটকে ঘিরে থাকা মানুষদের সমন্বয় করে। এটি কোচিং, উপস্থিতি, স্কুল ও পথচলার রেকর্ডের সঙ্গে যুক্ত হয়; কখনও সেগুলো কপি করে না।',
