  'arp.scope.athlete': 'ক্রীড়াবিদ',
  'arp.scope.campus': 'ক্যাম্পাস',
  'arp.scope.academy': 'একাডেমি',
  'arp.aud.progress': 'একাডেমির মালিক ও অ্যাডমিন, ক্রীড়াবিদের কোচ, ক্রীড়াবিদ এবং যাচাইকৃত অভিভাবক পড়তে পারেন। আর্থিক, চিকিৎসা বা কল্যাণ নোট এবং কোচ ও কর্মীদের ব্যক্তিগত মতামত কখনও অন্তর্ভুক্ত হয় না।',
  'arp.aud.term': 'উন্নয়ন প্রতিবেদনের একই পাঠক। টার্মের উপস্থিতি এবং শেয়ার করা থাকলে স্কুলের ব্যান্ড যোগ হয়। স্কুলের গ্রেড কখনও ছাপা হয় না।',
  'arp.aud.management': 'শুধু একাডেমির মালিক ও অ্যাডমিন পড়তে পারেন। ৩-এর কম সদস্যের দল সংখ্যা হিসেবে ছাপা হয় না। আইনি, চিকিৎসা বা কোচের ব্যক্তিগত তথ্য নেই।',
  'arp.aud.finance': 'শুধু একাডেমির মালিক, অ্যাডমিন ও অর্থ বিভাগ পড়তে পারে। ব্যবস্থাপনা হিসাব, বিধিবদ্ধ বা নিরীক্ষিত নয়। কোচিং বা চিকিৎসা তথ্য নেই।',
  'arp.aud.campus': 'শুধু একাডেমির মালিক ও অ্যাডমিন পড়তে পারেন। একটি ক্যাম্পাস: মানুষ, কার্যক্রম, কর্মী, অর্থ। ৩-এর কম সদস্যের দল সংখ্যা হিসেবে ছাপা হয় না।',
  'arp.basis.progress': 'ক্রীড়াবিদের জন্য নিরাপদ অগ্রগতি দৃশ্য: কোচের মূল্যায়ন, একাডেমির উপস্থিতি ও অনুমোদিত সরকারি ফল আলাদাভাবে।',
  'arp.basis.term': 'টার্মের অগ্রগতি দৃশ্য, টার্মের উপস্থিতি এবং শেয়ার করা থাকলে স্কুলের ব্যান্ড। কিছুই এক স্কোরে মেলানো হয় না।',
  'arp.basis.management': 'এক্সিকিউটিভ হোমের একই সংখ্যা থেকে ব্যবস্থাপনা দৃশ্য। বিধিবদ্ধ হিসাব নয়।',
  'arp.basis.finance': 'অর্থ খতিয়ান, অনুমোদিত বেতন তালিকা ও নিশ্চিত ভেন্যু বুকিং থেকে ব্যবস্থাপনা হিসাব। বিধিবদ্ধ বা নিরীক্ষিত নয়।',
