  'acc.mine_empty_title': 'কোনো অডিট নিযুক্ত নেই',
  'acc.mine_empty_sub': 'কোনো অ্যাকাডেমি আপনাকে পরিদর্শক মনোনীত করলে অডিটটি এখানে দেখা যাবে।',
  'guide.accreditation.title': 'স্বীকৃতি ও অডিট পরিচালনা করুন',
  'guide.accreditation.why': 'আপনার অ্যাকাডেমির প্রতিটি বাহ্যিক স্বীকৃতি, লাইসেন্স ও মান চিহ্ন ট্র্যাক করুন, প্রতিটির প্রমাণ আপনার বিদ্যমান নথির সঙ্গে সংযুক্ত রাখুন, এবং অনুসন্ধান ও সংশোধনমূলক পদক্ষেপসহ অডিট চালান, যা গোপনে বদলানো যায় না।',
  'guide.accreditation.s1': 'অ্যাকাডেমি খুলে স্বীকৃতিতে যান, তারপর কনফিগার চেপে একটি কাঠামো যোগ করুন: স্বীকৃতিদানকারী সংস্থা, ধরন, স্তর, দায়িত্বপ্রাপ্ত ব্যক্তি, নবায়ন চক্র ও স্মরণ করানোর সময়।',
  'guide.accreditation.s2': 'কাঠামোটি খুলুন, প্রমাণ বেছে নিন, যা প্রয়োজন তা যোগ করুন, তারপর কোচের যোগ্যতাপত্র ও সম্মতি নথি সংযুক্ত করুন। কিছু কপি হয় না, বৈধতা সরাসরি দেখা হয়।',
  'guide.accreditation.s3': 'অডিট নির্ধারণ করুন চাপুন, ধরন, তারিখ ও যাচাইয়ের ক্ষেত্র বেছে নিন, এবং চাইলে একজন পরিদর্শক মনোনীত করুন, যিনি শুধু সেই অডিট দেখবেন।',
  'guide.accreditation.s4': 'প্রতিটি অনুসন্ধান তার গুরুত্ব ও সংশোধনমূলক পদক্ষেপসহ নথিভুক্ত করুন, প্রতিটি পদক্ষেপে একজন দায়িত্বপ্রাপ্ত ও নির্ধারিত তারিখ দিন, এবং কাজ শেষ হলে সম্পন্ন চিহ্নিত করুন।',
  'guide.accreditation.s5': 'প্রতিটি উচ্চ ও মাঝারি অনুসন্ধানের সমাধান হলে পুনরায় জমা দিন, তারপর পরিদর্শকের সিদ্ধান্ত নথিভুক্ত করুন। প্রতিটি ধাপ একটি তালাবদ্ধ ধারায় সংরক্ষিত থাকে।',
