  'inc.lvl_exceeding': 'প্রত্যাশার চেয়ে এগিয়ে',
  'guide.inclusion.title': 'অন্তর্ভুক্তিমূলক ও অভিযোজিত কর্মসূচি পরিচালনা করুন',
  'guide.inclusion.why': 'প্রতিবন্ধী ও প্যারা ক্রীড়াবিদরা রোগ নির্ণয় প্রকাশ না করেই আপনার কর্মসূচিতে যোগ দিয়ে এগিয়ে যেতে পারবেন: কর্মসূচি কী দেয় তা ঠিক করুন, প্রতিটি অভিযোজিত সেশন প্রস্তুত কি না যাচাই করুন, আর ক্রীড়াবিদরা শুধু তাঁদের বেছে নেওয়া কার্যকরী প্রয়োজনগুলো জানান।',
  'guide.inclusion.s1': 'অ্যাকাডেমি খুলুন, তারপর অন্তর্ভুক্তি, তারপর কর্মসূচি সেটআপ, একটি কর্মসূচি বেছে নিন এবং কারা যোগ দিতে পারবে, খেলার অভিযোজন টেমপ্লেট, দেওয়া সমন্বয়, ভেন্যুর সুবিধা ও প্রয়োজনীয় সহায়ক-অনুপাত ঠিক করুন।',
  'guide.inclusion.s2': 'সেশন যাচাই করা যায় এমনভাবে প্রতিটি ভেন্যুর প্রবেশযোগ্যতার সুবিধা (লিফট, ধাপহীন পথ, প্রবেশযোগ্য চেঞ্জিং রুম, পুলের হোইস্ট) নথিভুক্ত করতে ভেন্যু ম্যানেজারদের বলুন।',
  'guide.inclusion.s3': 'ক্রীড়াবিদ, বা অল্পবয়সীর যাচাইকৃত অভিভাবক, আমার অ্যাকাডেমি, তারপর আবাসন-সহায়তা খুলে শুধু কর্মীদের যা দরকার তা, কার সঙ্গে এবং কত দিন পর্যন্ত, শেয়ার করেন। যেকোনো মুহূর্তে তাঁরা তা প্রত্যাহার করতে পারেন।',
  'guide.inclusion.s4': 'অন্তর্ভুক্তি, তারপর সেশন প্রস্তুতি খুলুন, একটি সেশন বেছে নিন এবং প্রতিটি ঘাটতি মেটান: ভেন্যু, সহায়ক ব্যক্তি, দায়িত্ব-কভার ও প্রধান কোচের যোগ্যতা। কোচ ও ভেন্যু কর্মীরা শুধু তাঁদের সঙ্গে শেয়ার করা তথ্যই দেখেন, এবং প্রতিটি দেখা ক্রীড়াবিদের জন্য লগ করা হয়।',
  'guide.inclusion.s5': 'বর্ণনামূলক স্তর দিয়ে অভিযোজিত, কোচ-পরিচালিত মূল্যায়ন নথিভুক্ত করুন, কখনও একক স্কোর নয়, এবং দ্বিতীয় মূল্যায়নকারীকে দিয়ে স্বাক্ষর করান। পরিচালকরা ওভারভিউতে শুধু সংখ্যা দেখেন।',


